  /// Returns a deterministic, pseudo-random quote that is identical
  /// across all devices on the same calendar day, online or offline.
  static String getTodayQuote() {
    final now = DateTime.now();
    // Fixed base reference date
    final int days = DateTime(now.year, now.month, now.day)
        .difference(DateTime(2026, 1, 1))
        .inDays;

    // 17 is coprime to 60 (gcd(17, 60) = 1).
    // This creates an unpredictable daily shuffle, but cycles through
    // every single quote exactly once before any quote is repeated.
    final int index = ((days * 17) % quotes.length).abs();
    return quotes[index];
  }
